<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Senate\SubordinatePersonaConsistencyBaselineTestimonyService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:complete-subordinate-persona-consistency-baseline-testimony',description:'Consume the exact Consistency testimony authority and seal the witness answer')]
final class SenateCompleteSubordinatePersonaConsistencyBaselineTestimonyCommand extends Command
{public function __construct(private readonly SubordinatePersonaConsistencyBaselineTestimonyService $service){parent::__construct();}protected function configure():void{$this->addArgument('question-record-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$record=$this->service->complete((string)$input->getArgument('question-record-id'));}catch(\Throwable $exception){$output->writeln('<error>REFUSED</error> '.$exception->getMessage());return self::FAILURE;}$output->writeln($input->getOption('json')?json_encode($record,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>SUBORDINATE_PERSONA_CONSISTENCY_BASELINE_TESTIMONY_SEALED_PENDING_SECURITY_QUESTION</info> '.$record['turn_id']);return self::SUCCESS;}}
